# Compute affine transform: H&E space → CosMx space
tform = estimate_transform('affine', he_landmarks, cosmx_landmarks)

# Test it — transformed H&E landmarks should be close to CosMx landmarks
print("Residuals (should be close to 0):")
print(tform(he_landmarks) - cosmx_landmarks)


he_test = np.array([[9030.18, 21720.87]])
cosmx_test = np.array([[117451.13, 59680.18]])

predicted = tform(he_test)
error = predicted - cosmx_test
print(f"4th point error: {error}")
print(f"Distance error: {np.sqrt((error**2).sum()):.1f} units")


